const elements = $json.elements || [];

const places = elements
  .filter(place => place.tags?.name)
  .map((place, index) => ({
    id: `place_${String(index + 1).padStart(3, "0")}`,
    name: place.tags.name,
    category:
      place.tags.tourism ||
      place.tags.historic ||
      place.tags.leisure ||
      "place",
    latitude: place.lat ?? place.center?.lat,
    longitude: place.lon ?? place.center?.lon,
    openingHours: place.tags.opening_hours || null,
    website: place.tags.website || null
  }));

return [
  {
    json: {
      places
    }
  }
];

const places = $('Places DTO').item.json.places.map(place => ({
  id: place.id,
  name: place.name,
  category: place.category
}));

return [
  {
    json: {
      places
    }
  }
];

