parameters.jsCode:
const content = $json.message?.content;

if (!content) {
  throw new Error("Qwen did not return any content.");
}

const result = JSON.parse(content);

const selectedPlaces = result.selectedPlaces || [];

const realPlaces = $('Places DTO').item.json.places || [];

const validatedPlaces = [];
const rejectedPlaces = [];

for (const selected of selectedPlaces) {

  const realPlace = realPlaces.find(
    place => place.id === selected.placeId
  );

  if (!realPlace) {
    rejectedPlaces.push({
      placeId: selected.placeId,
      reason: "Place ID not found in Places DTO"
    });

    continue;
  }

  validatedPlaces.push({
    ...realPlace,
    reason: selected.reason
  });
}

return [
  {
    json: {
      selectedPlaces: validatedPlaces,
      selectedCount: validatedPlaces.length,
      requestedCount: selectedPlaces.length,
      rejectedPlaces,
      grounded: rejectedPlaces.length === 0
    }
  }
];

const content = $json.message?.content;

if (!content) {
  throw new Error("Qwen itinerary planner did not return any content.");
}

const itinerary = JSON.parse(content);

const validatedPlaces =
  $('Validate Selected Places').first().json.selectedPlaces || [];

const validIds = new Set(
  validatedPlaces.map(place => place.id)
);

const invalidActivities = [];
const duplicateActivities = [];

const seenIds = new Set();

const cleanedDays = (itinerary.days || []).map(day => {

  const cleanedActivities = [];

  for (const activity of day.activities || []) {

    // Qwen 2 uses "id" because validated places use "id"
    const placeId = activity.id;

    // Missing place ID
    if (!placeId || placeId === "N/A") {
      invalidActivities.push({
        day: day.day,
        placeId: placeId || "N/A",
        reason: "Missing place ID"
      });

      continue;
    }

    // Place was not selected/validated
    if (!validIds.has(placeId)) {
      invalidActivities.push({
        day: day.day,
        placeId,
        reason: "Place ID was not in validated places"
      });

      continue;
    }

    // Duplicate
    if (seenIds.has(placeId)) {
      duplicateActivities.push({
        day: day.day,
        placeId,
        reason: "Place appeared more than once and was removed"
      });

      continue;
    }

    seenIds.add(placeId);

    cleanedActivities.push({
      time: activity.time,
      placeId,
      reason: activity.reason
    });
  }

  return {
    day: day.day,
    activities: cleanedActivities
  };
});

const validDayCount =
  cleanedDays.length === 2;

const validActivityCounts =
  validDayCount &&
  cleanedDays.every(
    day =>
      day.activities.length >= 1 &&
      day.activities.length <= 3
  );

const valid =
  validDayCount &&
  validActivityCounts;

return [
  {
    json: {
      itinerary: {
        ...itinerary,
        days: cleanedDays
      },

      valid,

      invalidActivities,

      duplicateActivities,

      validDayCount,

      validActivityCounts,

      debug: {
        dayCounts: cleanedDays.map(day => ({
          day: day.day,
          activityCount: day.activities.length
        }))
      }
    }
  }
];

const itineraryResult = $json;

if (!itineraryResult.valid) {
  throw new Error("Itinerary validation failed.");
}

const itinerary = itineraryResult.itinerary;

const weather =
  $('Travel Weather DTO').first().json;

const validatedPlaces =
  $('Validate Selected Places').first().json.selectedPlaces || [];

const placeMap = new Map(
  validatedPlaces.map(place => [
    place.id,
    place
  ])
);

const days = itinerary.days.map(day => ({
  day: day.day,

  activities: day.activities.map(activity => {

    const place = placeMap.get(activity.placeId);

    if (!place) {
      throw new Error(
        `Place ID ${activity.placeId} was not found in validated places.`
      );
    }

    return {
      time: activity.time,

      placeId: place.id,
      name: place.name,
      category: place.category,

      latitude: place.latitude,
      longitude: place.longitude,

      openingHours: place.openingHours,
      website: place.website,

      reason: activity.reason
    };
  })
}));

return [
  {
    json: {
      success: true,

      destination: {
        city: weather.city,
        country: weather.country,
        timezone: weather.timezone
      },

      weather: {
        temperature: weather.temperature,
        humidity: weather.humidity,
        windSpeed: weather.windSpeed
      },

      itinerary: {
        destination: itinerary.destination,
        summary: itinerary.summary,
        days
      }
    }
  }
];
